 r=read(P/'report.json');s=read(D/'sealed.json');p=read(D/'plan.json');pair=r['paired']['JointOffsetFusion-NativeG6'];source=r['paired']['JointOffsetFusion-Source'];block=r['paired']['JointOffsetFusion-BlockedOffsetFusion'];g=r['groups_vs_G6'];sg={name:{a:sum(100*(x['values'][a]['t']-x['values']['Source']['t'])for x in r['rows']if x['duration_group']==name)/sum(x['duration_group']==name for x in r['rows'])for a in p['arms']}for name in g};put(P/'source_duration_groups.json',sg)
 lines=['# Native event decoder with joint offset context','','Fixed exposed HC64, all64 queries. Interleave original Full-caption actual final-pass7 kwargs into65 physical nodes; each query/content/time/memory/position/padding value is unchanged. No additional encoder/text/fusion/expert/observation/optimizer. Six-layer original frozen time decoder/head; single legal interval posterior per layer, mean6, fixed half Global6/half joint; original MBR and spatial DP.','','Native decoder previously performs temporal self-attention separately for each offset. This test permits cross-offset interaction. Same-grid BlockedOffsetFusion masks ONLY cross-parity self-attention edges, keeping all inputs and legal boundary support. It isolates temporal interaction from changed pooling and cross-parity endpoint hypotheses. Existing motion features already contain their original clip context; no new independent visual evidence is created.','','Original time positions remain unchanged (adjacent parity nodes can share original slot). This is an intervention, not bitwise equivalent acceleration. Blocked and separate native calls have different kernel packing; actual hidden error is reported. Original separate native hidden/logits/posterior and saved Source/Native/spatial aliases must still match bitwise64.','','NativeMarginalFusion averages original two legal offset tables without hull. SelfHullFusion is explicitly the previous grammar-supported52/64 alias, not the main all64 matched control. ReverseJointFusion reverses per-frame memory/position/padding relative to unchanged query/time. Source/NativeG6/NoOp retained. All64 predictions sealed before independent official-label CPU scoring.','','|Arm|complete vIoU|tIoU|time +/−/=|time harm>5pp|','|---|---:|---:|---:|---:|']
 for a,m in r['means'].items():
  t=r['paired'].get(a+'-NativeG6',{}).get('t',{});lines.append(f"|{a}|{100*m['v']:.4f}|{100*m['t']:.4f}|{t.get('improved',0)}/{t.get('harmed',0)}/{t.get('unchanged',64)}|{t.get('severe_below_minus5pp',0)}|")
 lines+=['',f"Primary−Global6: v{pair['v']['mean']:+.4f}pp CI{pair['v']['CI95']}, t{pair['t']['mean']:+.4f}pp CI{pair['t']['CI95']}. Primary−Source: v{source['v']['mean']:+.4f}pp, t{source['t']['mean']:+.4f}pp.",f"Joint−identical blocked-grid: v{block['v']['mean']:+.4f}pp CI{block['v']['CI95']}, t{block['t']['mean']:+.4f}pp CI{block['t']['CI95']}.",f"Primary shortt{g['short_le5s']['JointOffsetFusion']['t']:+.4f}pp,longt{g['long_gt5s']['JointOffsetFusion']['t']:+.4f}pp vsG6; vsSource short{sg['short_le5s']['JointOffsetFusion']:+.4f},long{sg['long_gt5s']['JointOffsetFusion']:+.4f}pp."]
 passed=pair['v']['mean']>0 and pair['t']['mean']>0 and source['v']['mean']>0 and source['t']['mean']>0 and pair['t']['improved']>pair['t']['harmed'] and all(sg[x]['JointOffsetFusion']>0 for x in sg)and block['t']['mean']>0
 lines+=['','Basic development screen passes only; fixed HC/Vid recheck still required.'if passed else'Not qualified for main/full promotion. No position, density or fusion-weight sweep.',f"Actual blocked-vs-original native hidden maximum difference{s['blocked_native_hidden_max_error']:.6g}; original separate no-op remains bitwise. Official/dense checks{r['checks']} maxerror{r['max_metric_error']:.3g}. Worker{s['seconds']:.2f}s including loading/research recording, not deployment end-to-end. Calls{s['counts']}.",'','[Signed outcomes](signed.tsv), [severe tails](severe_declines.tsv), [all Source duration groups](source_duration_groups.json), [protocol](protocol.json).']
 (P/'ANALYSIS.md').write_text('\n'.join(lines)+'\n');put(P/'verification.json',dict(queries=64,supported=64,native_hidden_logits_posterior_bitwise=64,per_node_interleave_inverse_exact=64,scoped_block_mask_and_cleanup=True,all64_seal_before_GT=True,official_dense_checks=r['checks'],max_metric_error=r['max_metric_error'],blocked_native_hidden_max_error=s['blocked_native_hidden_max_error'],paper_sources_unchanged=48,provider_sources_unchanged=434,weights_frozen=s['network_weights_frozen'],promoted=False,basic_development_screen=passed,seal_sha256=sha(D/'sealed.json')))
